float read_be_float(std::span<const std::byte, 4> bytes) {
    std::uint32_t image;
    std::memcpy(&image, bytes.data(), sizeof(image));
    if constexpr (std::endian::native == std::endian::little) {
        image = std::byteswap(image);
    }
    return std::bit_cast<float>(image);
}

int main() {
    const std::byte wire[]{std::byte{0x3F}, std::byte{0xC0},
                           std::byte{0x00}, std::byte{0x00}};

    const float value = read_be_float(std::span<const std::byte, 4>{wire});
    std::cout << value << ' '
              << (std::bit_cast<std::uint32_t>(value) == 0x3FC00000u) << '\n';
}

