#include <cstdint>
#include <functional>

struct Glyph {
    char32_t code;
    std::uint8_t page;
    float advance;
};

bool same_glyph(const Glyph& left, const Glyph& right) noexcept {
    return left.code == right.code && left.page == right.page &&
           left.advance == right.advance;
}

// The old implementation hashed sizeof(Glyph) bytes, which includes the three
// padding bytes after the page member. Member assignment promises nothing
// about padding,
// so two equal keys built in different storage could hash differently and miss.
std::size_t glyph_hash(const Glyph& glyph) noexcept {
    std::size_t seed = std::hash<char32_t>{}(glyph.code);
    seed = seed * 1000003U ^ std::hash<std::uint8_t>{}(glyph.page);
    seed = seed * 1000003U ^ std::hash<float>{}(glyph.advance);
    return seed;
}

