template <class Compare>
class ScoreTable {
public:
    explicit ScoreTable(Compare compare = Compare{}) : compare_(compare) {}

    bool prefers(std::uint32_t left, std::uint32_t right) const {
        return compare_(left, right);
    }

    std::uint32_t size() const noexcept { return count_; }

private:
    [[no_unique_address]] Compare compare_;
    std::uint32_t count_{};
};

struct HigherScore {
    bool operator()(std::uint32_t left, std::uint32_t right) const {
        return left > right;
    }
};

struct AboveFloor {
    std::uint32_t floor_value;
    bool operator()(std::uint32_t left, std::uint32_t right) const {
        return (left > floor_value) && (left > right);
    }
};

static_assert(sizeof(ScoreTable<HigherScore>) == 4);
static_assert(sizeof(ScoreTable<AboveFloor>) == 8);

