#include <cstdint>
#include <stdexcept>

class Cell {
public:
    enum class Kind { index, weight };

    Cell() noexcept : index_(0), kind_(Kind::index) {}

    void set_index(std::uint32_t value) noexcept {
        index_ = value;               // begins index_'s lifetime
        kind_ = Kind::index;
    }

    void set_weight(float value) noexcept {
        weight_ = value;              // begins weight_'s lifetime
        kind_ = Kind::weight;
    }

    std::uint32_t index() const {
        if (kind_ != Kind::index) {
            throw std::logic_error{"cell does not hold an index"};
        }
        return index_;
    }

    float weight() const {
        if (kind_ != Kind::weight) {
            throw std::logic_error{"cell does not hold a weight"};
        }
        return weight_;
    }

private:
    // Reading the inactive member is undefined behaviour in C++, even though
    // the bytes exist and one compiler may return the expected bit pattern.
    // The common-initial-sequence exception covers only union members that are
    // standard-layout structs sharing a matching leading run of members, so a
    // union of a plain uint32_t and a plain float gets nothing from it.
    union {
        std::uint32_t index_;
        float weight_;
    };
    Kind kind_;
};

#include <bit>
#include <cstdint>

static_assert(sizeof(float) == sizeof(std::uint32_t));

constexpr bool has_sign_bit(float value) {
    return (std::bit_cast<std::uint32_t>(value) >> 31) != 0U;
}

constexpr float with_sign_bit_cleared(float value) {
    return std::bit_cast<float>(std::bit_cast<std::uint32_t>(value) &
                                0x7FFFFFFFU);
}

static_assert(has_sign_bit(-0.0f));
static_assert(!has_sign_bit(0.0f));
static_assert(with_sign_bit_cleared(-2.5f) == 2.5f);

#include <cstddef>
#include <cstdint>
#include <span>
#include <stdexcept>

// Shifting the value itself is host-order independent: the arithmetic works on
// the value, not on its stored bytes, so no endian test is needed.
void write_be48(std::span<std::byte, 6> bytes, std::uint64_t value) {
    if (value >= (std::uint64_t{1} << 48)) {
        throw std::out_of_range{"timestamp does not fit in 48 bits"};
    }
    for (std::size_t i = 0; i < 6; ++i) {
        const unsigned shift = static_cast<unsigned>(8 * (5 - i));
        bytes[i] = static_cast<std::byte>((value >> shift) & 0xFFU);
    }
}

std::uint64_t read_be48(std::span<const std::byte, 6> bytes) {
    std::uint64_t value = 0;
    for (std::size_t i = 0; i < 6; ++i) {
        value = (value << 8) | std::to_integer<std::uint64_t>(bytes[i]);
    }
    return value;
}

#include <bit>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <span>
#include <stdexcept>
#include <type_traits>

struct ChunkHeader {
    std::uint64_t chunk_id;
    std::uint32_t tile_count;
    std::uint32_t checksum;
    std::uint16_t layer;
    std::byte compression;
    std::byte flags;
    std::uint32_t payload_length;
};

static_assert(std::is_trivially_copyable_v<ChunkHeader>);
static_assert(std::is_standard_layout_v<ChunkHeader>);
static_assert(sizeof(ChunkHeader) == 24);
static_assert(alignof(ChunkHeader) == 8);
static_assert(offsetof(ChunkHeader, chunk_id) == 0);
static_assert(offsetof(ChunkHeader, tile_count) == 8);
static_assert(offsetof(ChunkHeader, checksum) == 12);
static_assert(offsetof(ChunkHeader, layer) == 16);
static_assert(offsetof(ChunkHeader, compression) == 18);
static_assert(offsetof(ChunkHeader, flags) == 19);
static_assert(offsetof(ChunkHeader, payload_length) == 20);

ChunkHeader parse_chunk(std::span<const std::byte> buffer) {
    if (buffer.size() < sizeof(ChunkHeader)) {
        throw std::invalid_argument{"short chunk header"};
    }

    ChunkHeader header;
    std::memcpy(&header, buffer.data(), sizeof(header));

    if constexpr (std::endian::native == std::endian::little) {
        header.chunk_id = std::byteswap(header.chunk_id);
        header.tile_count = std::byteswap(header.tile_count);
        header.checksum = std::byteswap(header.checksum);
        header.layer = std::byteswap(header.layer);
        header.payload_length = std::byteswap(header.payload_length);
    }
    return header;
}
